import {db,request,USE_MOCK} from './apiClient.js';
const delay=()=>new Promise(r=>setTimeout(r,110));
export async function listBooks(){if(!USE_MOCK)return request('/books');await delay();return db.read().books}
export async function createBorrowRequest(bookId){if(!USE_MOCK)return request('/borrow-requests',{method:'POST',body:{bookId}});let d=db.read(),b=d.books.find(x=>x.id===bookId);if(!b||b.stock<=0)throw Error('Sách đã hết, vui lòng chọn sách khác.');let item={id:db.id('REQ'),user:'SV Nguyễn An',bookId,status:'Chờ duyệt',created:new Date().toISOString().slice(0,10)};d.requests.unshift(item);d.notifications.unshift({id:Date.now(),title:'Đã gửi yêu cầu '+item.id,detail:'Yêu cầu đang chờ thủ thư duyệt.',read:false});db.write(d);return item}
export async function reviewRequest(id,approved){if(!USE_MOCK)return request(`/borrow-requests/${id}/review`,{method:'PATCH',body:{approved}});let d=db.read(),r=d.requests.find(x=>x.id===id);if(!r||r.status!=='Chờ duyệt')throw Error('Yêu cầu không còn chờ duyệt');let b=d.books.find(x=>x.id===r.bookId);if(approved&&(!b||b.stock<1))throw Error('Không đủ sách trong kho');r.status=approved?'Đã duyệt':'Từ chối';if(approved){b.stock--;let due=new Date();due.setDate(due.getDate()+14);d.loans.unshift({id:db.id('LN'),user:r.user,bookId:r.bookId,due:due.toISOString().slice(0,10),status:'Đang mượn'})}db.write(d);return r}
export async function returnLoan(id){if(!USE_MOCK)return request(`/loans/${id}/return`,{method:'PATCH'});let d=db.read(),l=d.loans.find(x=>x.id===id);if(!l||l.status!=='Đang mượn')throw Error('Phiếu mượn không hợp lệ');l.status='Đã trả';l.returned=new Date().toISOString().slice(0,10);let b=d.books.find(x=>x.id===l.bookId);if(b)b.stock++;db.write(d);return l}
export async function addBook(book){if(!USE_MOCK)return request('/books',{method:'POST',body:book});let d=db.read();if(d.books.some(x=>x.id===book.id||x.isbn===book.isbn))throw Error('Mã sách hoặc ISBN đã tồn tại');d.books.unshift({...book,stock:Number(book.stock),total:Number(book.stock),emoji:'📘'});db.write(d)}
export async function patchBook(id,changes){if(!USE_MOCK)return request(`/books/${id}`,{method:'PATCH',body:changes});let d=db.read(),b=d.books.find(x=>x.id===id);if(!b)throw Error('Không tìm thấy sách');Object.assign(b,changes);db.write(d)}
export async function submitRenewal(id){if(!USE_MOCK)return request('/renewals',{method:'POST',body:{loanId:id}});let d=db.read();if(d.renewals.some(x=>x.loanId===id&&x.status==='Chờ duyệt'))throw Error('Đã có yêu cầu gia hạn đang chờ');d.renewals.unshift({id:db.id('RN'),loanId:id,status:'Chờ duyệt'});db.write(d)}
export async function reviewRenewal(id,approved){if(!USE_MOCK)return request(`/renewals/${id}/review`,{method:'PATCH',body:{approved}});let d=db.read(),r=d.renewals.find(x=>x.id===id);if(!r)throw Error('Không tìm thấy yêu cầu');r.status=approved?'Đã duyệt':'Từ chối';if(approved){let l=d.loans.find(x=>x.id===r.loanId);if(l){let date=new Date(l.due+'T12:00:00');date.setDate(date.getDate()+7);l.due=date.toISOString().slice(0,10)}}db.write(d)}
